    bos.write4Bytes(IcnsType.ICNS_16x16_32BIT_IMAGE.getType());
    bos.write4Bytes(4 + 4 + 4 * 16 * 16);
    for (int y = 0; y < 16; y++) {
        for (int x = 0; x < 16; x++) {
