@Test
public void testVectors() throws Exception {
    final float[] originalData = new float[8];
    for (int i = 0; i < 8; i++) {
        originalData[i] = i;
    }
    final float[] transformed = REFERENCE_forwardDCT(originalData);
    final float[] reversed = REFERENCE_inverseDCT(transformed);
    for (int i = 0; i < 8; i++) {
        assertEquals("Reference transforms broken, at x=" + i, originalData[i], reversed[i], 0.001);
    }
    final float[] data = originalData.clone();
    Dct.forwardDCT8(data);
    Dct.scaleQuantizationVector(data);
    for (int i = 0; i < 8; i++) {
        assertEquals("Forward transform broken, at x=" + i, data[i], transformed[i], 0.001);
    }
    Dct.scaleDequantizationVector(data);
    Dct.inverseDCT8(data);
    for (int i = 0; i < 8; i++) {
        assertEquals("Inverse transform broken, at x=" + i, data[i], originalData[i], 0.001);
    }
}

@Test
public void testMatrices() throws Exception {
    final float[] originalData = new float[8 * 8];
    final float[][] originalData8x8 = new float[8][8];
    for (int y = 0; y < 8; y++) {
        for (int x = 0; x < 8; x++) {
            final float value = 8 * y + x;
            originalData8x8[y][x] = value;
            originalData[8 * y + x] = value;
        }
    }
    final float[][] transformed8x8 = REFERENCE_forwardDCT(originalData8x8);
    final float[][] reversed8x8 = REFERENCE_inverseDCT(transformed8x8);
    for (int y = 0; y < 8; y++) {
        for (int x = 0; x < 8; x++) {
            assertEquals("Reference transforms broken, at x=" + x + ",y=" + y, originalData8x8[y][x], reversed8x8[y][x], 0.001);
        }
    }
    final float[] data = originalData.clone();
    Dct.forwardDCT8x8(data);
    Dct.scaleQuantizationMatrix(data);
    for (int y = 0; y < 8; y++) {
        for (int x = 0; x < 8; x++) {
            assertEquals("Forward transform broken, at x=" + x + ",y=" + y, transformed8x8[y][x], data[8 * y + x], 0.001);
        }
    }
    Dct.scaleDequantizationMatrix(data);
    Dct.inverseDCT8x8(data);
    for (int y = 0; y < 8; y++) {
        for (int x = 0; x < 8; x++) {
            assertEquals("Inverse transform broken, at x=" + x + ",y=" + y, originalData8x8[y][x], data[8 * y + x], 0.001);
        }
    }
}

@Test
public void testSingleImage() throws Exception {
    final File imageFile = getTestImageByName("Canon Powershot SD750 - 2007.12.26.n.IMG_3704.JPG");
    final Map<String, Object> params = new HashMap<String, Object>();
    final ImageMetadata metadata = Imaging.getMetadata(imageFile, params);
    assertNotNull(metadata);
    final JpegImageMetadata jpegMetadata = (JpegImageMetadata) metadata;
    // note that exif might be null if no Exif metadata is found.
    final TiffImageMetadata exif = jpegMetadata.getExif();
    final List<TiffField> fields = exif.getAllFields();
    final Map<Integer, TiffField> fieldMap = new HashMap<Integer, TiffField>();
    // Build a simplified field tag -> field map, ignoring directory
    // structures.
    // Good enough for our purposes, since the image in question is known.
    for (final TiffField field : fields) {
        fieldMap.put(field.getTag(), field);
    }
    final Map<Integer, Object> expectedFieldValues = new HashMap<Integer, Object>();
    expectedFieldValues.put(TiffTagConstants.TIFF_TAG_MAKE.tag, "Canon");
    expectedFieldValues.put(TiffTagConstants.TIFF_TAG_MODEL.tag, "Canon PowerShot SD750");
    expectedFieldValues.put(TiffTagConstants.TIFF_TAG_DATE_TIME.tag, "2007:12:25 13:34:39");
    for (Map.Entry<Integer, Object> tag : expectedFieldValues.entrySet()) {
        assertTrue(fieldMap.containsKey(tag.getKey()));
        final TiffField field = fieldMap.get(tag.getKey());
        assertNotNull(field);
        final Object value = field.getValue();
        assertNotNull(value);
        assertEquals(value, tag.getValue());
    }
}

